#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

// Пейлоад запускается по нажатию кнопки BOOT (GPIO 0)
const int TRIGGER_PIN = 0;

void typeLine(const char* text) {
  Keyboard.print(text);
  delay(100);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
}

void runPayload() {
  // Ждём, пока система точно распознает клавиатуру
  delay(1500);

  // Win+R -> cmd -> Enter
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(120);
  Keyboard.releaseAll();
  delay(1000);

  Keyboard.print("cmd");
  delay(300);
  Keyboard.press(KEY_RETURN);
  Keyboard.releaseAll();
  delay(1500);  // ждём, пока откроется окно cmd

  // color 2 — зелёный текст
  typeLine("color 2");
  delay(500);

  // dir /s — рекурсивный список файлов
  typeLine("dir/s");
}

void setup() {
  pinMode(TRIGGER_PIN, INPUT_PULLUP);

  Keyboard.begin();
  USB.begin();
  // После включения системе нужно несколько секунд на энумерацию USB-устройства
  delay(3000);
}

void loop() {
  if (digitalRead(TRIGGER_PIN) == LOW) {
    delay(80);            // антидребезг
    runPayload();
    // небольшая пауза, чтобы не сработать повторно, пока кнопку держат
    while (digitalRead(TRIGGER_PIN) == LOW) delay(10);
  }
  delay(10);
}
